import runpy,pprint,json,random
root=Path('/Users/johnbrophy/tigertest-next20-frvtc'); p=root/'tools/next20/frvtc'; old=json.loads((root/'data/france-vtc-questions.json').read_text()); modules={x:runpy.run_path(str(p/(x+'.py')))['ROWS'] for x in ['commercial','t3p','reglementation','securite']}
