change('securite',28,exp='Le retard supplémentaire est de 0,5 seconde, soit 20 × 0,5 = 10 m. Les valeurs de cet exemple sont fictives, pas un délai universel.')
change('securite',26,stem='Un médicament porte le pictogramme orange de niveau 2. Quelle précaution prendre avant de conduire ?',opts=["Lire la notice sans demander d'avis sur la conduite", 'Demander conseil à son médecin ou à son pharmacien', 'Attendre systématiquement la fin du traitement pour reprendre le volant', 'Décaler la prise au soir sans consulter le prescripteur'],exp="Le niveau 2 demande de prendre l'avis d'un professionnel de santé avant de conduire. La simple lecture de la notice correspond au niveau 1 ; ce pictogramme ne fixe pas, à lui seul, une interdiction jusqu'à la fin du traitement ni un nouvel horaire de prise.")
change('securite',16,stem="En ville, un autobus annonce son départ de l'arrêt devant vous. Quelle obligation avez-vous ?",opts=["Passer avant lui tant qu'il n'a pas franchi le marquage", "Maintenir votre allure jusqu'à ce qu'il ait quitté son arrêt", "Faciliter son départ, au besoin en vous arrêtant", "Vous arrêter systématiquement même s'il dispose d'une voie libre"])
change('commercial',23,opts=["Le gestionnaire des déplacements domicile-travail des salariés", "La coordinatrice des expéditions de marchandises aux clients", "Le responsable des locations de véhicules sans chauffeur", "La responsable des réservations de voyages d'affaires"],exp="L'offre de transferts pour les déplacements professionnels est directement liée aux réservations de voyages d'affaires. Les autres fonctions portent sur les trajets domicile-travail, les marchandises ou la location sans chauffeur ; une adresse professionnelle ne suffit pas à établir ce lien.")
change('commercial',6,stem="Une nouvelle liaison ferroviaire dessert l'aéroport. Quelle donnée permet d'estimer son effet concurrentiel sur vos transferts ?",opts=["Le montant de votre dernière facture d'entretien", "Le nombre de véhicules déjà présents dans votre parc", "Le délai de paiement accordé à votre principal client", "La part de vos trajets couverts aux horaires de cette liaison"],exp="Pour évaluer cette concurrence, il faut savoir dans quelle mesure le train répond aux mêmes besoins de trajet et d'horaire que votre offre. Les autres données décrivent l'exploitation interne, sans mesurer ce recoupement.",obj='Mesurer le recoupement entre une offre de substitution et les trajets vendus')
for m,rows in modules.items():(p/(m+'.py')).write_text('"""Original source-backed items; corrective design in revision-plan-v2.md."""\nROWS = '+pprint.pformat(rows,width=110,sort_dicts=False)+'\n')
