changed=[q for q,o in zip(b,old) if q!=o];out=Path('/Users/johnbrophy/tigertest-next20-progress/frvtc-review-final-changes');out.mkdir(exist_ok=True);(out/'changed-ids.json').write_text(json.dumps([q['questionId'] for q in changed],indent=2)+'\n');(out/'before.json').write_text(json.dumps([q for q in old if q['questionId'] in {x['questionId'] for x in changed}],ensure_ascii=False,indent=2)+'\n')
