for i,q in enumerate(changed,1):
 rid=f'F{i:03}';letters=list('ABCD');rng.shuffle(letters);private[rid]={'questionId':q['questionId'],'correctAnswer':'ABCD'[letters.index(q['correctAnswer'])]};blind.append(dict(id=rid,question=q['question'],**{'option'+a:q['option'+z] for a,z in zip('ABCD',letters)}))
